import pandas as pd

# Criteria and weights (higher = more important)
weights = {
    "SM Embedding": 1.6,
    "Falsifiability": 1.5,
    "Gravity": 1.3,
    "UV Completion": 1.2,
    "Quantization": 1.1,
    "Simplicity": 1.0,
    "Cosmology": 0.8,
    "Maturity": 0.5
}

# Emoji grades mapped to numeric scores
grade_to_score = {"✅": 2, "⚠️": 1, "❌": 0}

# Scorecard with emojis from the last message
data_emojis = {
    "Simplicity": {
        "SAT/Blockwave": "✅", "String Theory": "❌", "Loop QG": "✅",
        "Asymptotic Safety": "✅", "Causal Sets/CDT": "✅", "Noncomm. Geometry": "⚠️"
    },
    "Quantization": {
        "SAT/Blockwave": "✅", "String Theory": "❌", "Loop QG": "✅",
        "Asymptotic Safety": "❌", "Causal Sets/CDT": "✅", "Noncomm. Geometry": "✅"
    },
    "SM Embedding": {
        "SAT/Blockwave": "✅", "String Theory": "✅", "Loop QG": "❌",
        "Asymptotic Safety": "⚠️", "Causal Sets/CDT": "❌", "Noncomm. Geometry": "✅"
    },
    "Gravity": {
        "SAT/Blockwave": "✅", "String Theory": "✅", "Loop QG": "✅",
        "Asymptotic Safety": "✅", "Causal Sets/CDT": "✅", "Noncomm. Geometry": "✅"
    },
    "Cosmology": {
        "SAT/Blockwave": "⚠️", "String Theory": "⚠️", "Loop QG": "⚠️",
        "Asymptotic Safety": "⚠️", "Causal Sets/CDT": "✅", "Noncomm. Geometry": "⚠️"
    },
    "UV Completion": {
        "SAT/Blockwave": "⚠️", "String Theory": "✅", "Loop QG": "⚠️",
        "Asymptotic Safety": "✅", "Causal Sets/CDT": "✅", "Noncomm. Geometry": "⚠️"
    },
    "Falsifiability": {
        "SAT/Blockwave": "✅", "String Theory": "❌", "Loop QG": "⚠️",
        "Asymptotic Safety": "⚠️", "Causal Sets/CDT": "❌", "Noncomm. Geometry": "⚠️"
    },
    "Maturity": {
        "SAT/Blockwave": "❌", "String Theory": "✅", "Loop QG": "✅",
        "Asymptotic Safety": "✅", "Causal Sets/CDT": "⚠️", "Noncomm. Geometry": "⚠️"
    }
}

# Convert emojis to numeric scores and compute weighted totals
theories = ["SAT/Blockwave", "String Theory", "Loop QG", "Asymptotic Safety", "Causal Sets/CDT", "Noncomm. Geometry"]

# Build DataFrame of numeric scores
df_scores = pd.DataFrame({
    crit: {th: grade_to_score[data_emojis[crit][th]] for th in theories}
    for crit in data_emojis
}).T

# Reorder to our weight order
df_scores = df_scores.loc[list(weights.keys())]

# Weighted score per theory
import numpy as np
w = np.array([weights[c] for c in df_scores.index])
weighted = (df_scores.mul(w, axis=0)).sum(axis=0)

# Normalize to 0-100 scale (max is 2 * sum(weights))
max_score = 2 * sum(weights.values())
percent = (weighted / max_score * 100).round(1)

# Build a pretty table with emojis, numeric, weighted, percent
df_emojis = pd.DataFrame({crit: {th: data_emojis[crit][th] for th in theories} for crit in data_emojis}).T
df_emojis = df_emojis.loc[list(weights.keys())]

summary = pd.DataFrame({
    "Weighted Score": weighted.round(2),
    "Score (0-100)": percent
}).loc[theories]

summary_sorted = summary.sort_values("Score (0-100)", ascending=False)

import caas_jupyter_tools as cj
cj.display_dataframe_to_user("Weighted TOE Scorecard (with totals)", summary_sorted)

summary_sorted

